def compute(vars):
    rates = {
        "fiscal 2019": vars["v1"],
        "fiscal 2018": vars["v2"],
        "fiscal 2017": vars["v3"],
    }
    year = max(rates, key=rates.get)
    return {
        "value": year,
        "trace": {
            "rates": rates,
            "largest_rate": rates[year],
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "year"
            }
        }
    }
